    Translate the natural language version to a Lean 4 version:
    \begin{lstlisting}
theorem abs_sum_leq_sum_abs (n : ℕ) (f : ℕ → ℂ) :
abs (∑ i in Finset.range n, f i) ≤ ∑ i in Finset.range n, abs (f i) :=
\end{lstlisting}

