[AddCommGroup V] [Module K V] {n : Type*} {B : BilinForm K V}
{v : n → V} (hv₁ : B.iIsOrtho v)
(hv₂ : ∀ (i : n), ¬B.IsOrtho (v i) (v i)) :
LinearIndependent K v :=
