{t : Finset V} (h : FiniteDimensional.finrank K V + 1 < t.card) :
∃ (f : V → K), t.sum (λ (e : V) => f e • e) = 0 ∧ t.sum (λ (e : V) => f e) = 0
∧ ∃ (x : V) (H : x ∈ t), f x ≠ 0 :=
