{H : Subgroup G} (hH : Fintype.card H = p ^ n) :
Fintype.card (normalizer H / Subgroup.comap ((normalizer H).subtype : normalizer H →* G) H) ≡
  Fintype.card (G / H) [MOD p] :=
\end{lstlisting}

